solution.code:
import { readFileSync } from "fs";

const n = Number(readFileSync(0, "utf8").trim());

// F(90) は約 2.9 × 10¹⁸ なので BigInt で計算する
let prev = 0n;
let cur = 1n;
for (let i = 0; i < n; i++) {
  [prev, cur] = [cur, prev + cur];
}
console.log(prev.toString());
